<script setup lang="ts">
import { ref,onMounted,onBeforeUnmount } from 'vue'
import { learningApi,type LearningToday } from '@/api/learning'
import { authStore } from '@/stores/auth'
const data=ref<LearningToday>(),error=ref(''),controller=new AbortController()
async function load(){try{const result=await learningApi.today(controller.signal);if(!controller.signal.aborted)data.value=result}catch(e){if(!controller.signal.aborted)error.value=(e as Error).message}}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template><section class="today-learning"><header><div><p class="page-kicker">ONE STEP AT A TIME</p><h2>今天，接着学</h2></div><RouterLink to="/app/learning">学习统计与周报 →</RouterLink></header><p v-if="error" role="status">学习记录暂时未能加载。<button class="button" @click="load">重试</button></p><div v-if="data" class="today-learning-grid"><RouterLink v-if="authStore.has('vocabulary:use')" to="/app/vocabulary"><strong>{{data.dueWords}} 词待复习</strong><span>{{data.unfinishedWords}} 词正在学习 · 接续原进度 →</span></RouterLink><RouterLink v-if="authStore.has('research:use')" to="/app/research?tab=cards"><strong>{{data.dueCards}} 张复习卡到期</strong><span>先回忆，再核对答案 →</span></RouterLink><RouterLink v-if="authStore.has('note:read')" :to="authStore.has('note:write')&&data.notes[0]?data.notes[0].url:'/app/notes'"><strong>{{data.notes[0]?.title||'写下今天的收获'}}</strong><span>继续最近的笔记 →</span></RouterLink></div></section></template>
<style scoped>.today-learning{padding:28px 0 34px;border-top:1px solid var(--line);margin-top:24px}.today-learning header{display:flex;align-items:center;justify-content:space-between;gap:20px}.today-learning h2{font-size:24px;margin:8px 0 22px}.today-learning header>a{font-size:13px;text-decoration:none}.today-learning-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.today-learning-grid>a{padding:20px 0;border-bottom:1px solid var(--line);text-decoration:none;transition:border-color .2s}.today-learning-grid>a:hover{border-color:var(--green)}strong{display:block;font-size:18px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}span{display:block;margin-top:10px;font-size:13px;color:var(--muted)}@media(max-width:800px){.today-learning-grid{grid-template-columns:1fr}}</style>
